@Override public void onTimelineChanged(Timeline timeline, int reason) {
  if (progressState != PROGRESS_STATE_WAITING_FOR_AVAILABILITY) {
    return;
  }
  Timeline.Window window = new Timeline.Window();
  try {
    timeline.getWindow(0, window);
    if (!window.isPlaceholder) {
      long durationUs = window.durationUs;
      progressState = durationUs <= 0 || durationUs == C.TIME_UNSET ? PROGRESS_STATE_UNAVAILABLE : PROGRESS_STATE_AVAILABLE;
      assetLoaderListener.onDurationUs(window.durationUs);
    }
  } catch (IndexOutOfBoundsException e) {
    // Handle the exception, e.g., log the error or take a recovery action
  }
}
